program.source:
Interface MedioDePago
  Method Cobrar(monto As Integer) As Integer;
EndInterface

Class Efectivo Implements MedioDePago
  Method Cobrar(monto As Integer) As Integer
    Return monto;
  EndMethod
EndClass

Class Tarjeta Implements MedioDePago
  Method Cobrar(monto As Integer) As Integer
    Return monto + monto * 5 Div 100;
  EndMethod
EndClass

Class Vale Implements MedioDePago
  Private Define disponible As Integer;

  Method Constructor(saldo As Integer)
    This.disponible <- saldo;
  EndMethod

  Method Cobrar(monto As Integer) As Integer
    If monto > This.disponible Then
      Return This.disponible;
    EndIf
    Return monto;
  EndMethod
EndClass

Subroutine CobrarCon<T: MedioDePago>(medio As T, monto As Integer) As Integer
  Return medio.Cobrar(monto);
EndSubroutine

Algorithm Caja
  Define medio, monto As Integer;
  Read medio;
  Read monto;
  If medio = 1 Then
    Write CobrarCon(New Efectivo(), monto);
  Else
    If medio = 2 Then
      Write CobrarCon(New Tarjeta(), monto);
    Else
      Write CobrarCon(New Vale(15), monto);
    EndIf
  EndIf
EndAlgorithm

